158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
161	        Owner owner = this.clinicService.findOwnerById(ownerId);
162	        if (owner == null) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
171	        // Idempotent create: when the request carries an 'Idempotency-Key' already seen on a
172	        // previous successful create, return the originally created owner with 200 instead of
173	        // creating a duplicate.
174	        String idempotencyKey = currentIdempotencyKey();
175	        if (idempotencyKey != null) {
176	            Integer existingId = idempotentCreates.get(idempotencyKey);
177	            if (existingId != null) {
178	                Owner existing = this.clinicService.findOwnerById(existingId);
179	                if (existing != null) {
180	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
181	                }
182	            }
183	        }
184	        // Validate & normalize the optional email; reject the create when it is present but invalid.
185	        if (!normalizeEmail(ownerFieldsDto)) {
186	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
187	        }
188	        // Validate & normalize the optional postcode; reject the create when it is present but
189	        // not valid for the owner's city (see normalizePostcode).
190	        if (!normalizePostcode(ownerFieldsDto)) {
191	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
192	        }
193	        // Normalize the supplied address — the structured 'addressLine1'/'addressLine2' when
194	        // present, otherwise the flat 'address' — storing the normalized form (and the composed
195	        // 'address') back on the DTO so it is what gets persisted and compared. Reject the create
196	        // when no address is supplied in either form (see normalizeAddresses).
197	        if (!normalizeAddresses(ownerFieldsDto)) {
198	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
199	        }
200	        // Reject the create when the owner's city is already at capacity, i.e. it already
201	        // contains 50 or more owners (compared case-insensitively).
202	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
203	            return new ResponseEntity<>(HttpStatus.CONFLICT);
204	        }
205	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
206	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
207	        if (normalizedTelephone == null) {
208	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
209	        }
210	        ownerFieldsDto.setTelephone(normalizedTelephone);
211	        // Consolidated duplicate detection. All former separate telephone, email and household
212	        // duplicate checks are now expressed through the single derived identity key
213	        // '<normalizedTelephone>|<email or empty>|<householdId>' (see OwnerMapper#identityKey).
214	        // A create is rejected only when the new owner's identity collides with an existing owner's.
215	        // Because the telephone is part of the identity, two members of the same household with
216	        // different telephones no longer collide and are both allowed; only owners that share the
217	        // same normalized telephone and email are treated as the same identity.
218	        Owner candidate = ownerMapper.toOwner(ownerFieldsDto);
219	        String contactIdentity = identityContact(candidate);
220	        boolean identityInUse = this.clinicService.findAllOwners().stream()
221	            .filter(existing -> !existing.isDeleted())
222	            .anyMatch(existing -> contactIdentity.equals(identityContact(existing)));
223	        if (identityInUse) {
224	            return new ResponseEntity<>(HttpStatus.CONFLICT);
225	        }
226	        // Household membership keyed on the deterministic householdId, derived from the normalized
227	        // last name and postcode (see OwnerMapper#householdId). Owners sharing a last name and
228	        // postcode share the same household. A new owner joining an existing household is allowed
229	        // whenever it carries a distinct contact identity (its telephone/email do not collide with
230	        // an existing member) — hard identity duplicates were already rejected above. A collision on
231	        // the whole household identity (same household and same contact) is only permitted when the
232	        // request declares 'sharesHousehold', in which case it is created as a declared member.
233	        String householdId = ownerMapper.householdId(candidate);
234	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
235	            .filter(existing -> !existing.isDeleted())
236	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
237	            .toList();
238	        boolean householdExists = !householdMembers.isEmpty();
239	        boolean contactCollides = householdMembers.stream()
240	            .anyMatch(existing -> contactIdentity.equals(identityContact(existing)));
241	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
242	        if (householdExists && contactCollides && !sharesHousehold) {
243	            return new ResponseEntity<>(HttpStatus.CONFLICT);
244	        }
245	        boolean declaredMember = householdExists && sharesHousehold;
246	        // Determine the effective registration date — the value supplied on the request, or the
247	        // server's current date when none was supplied — and roll it forward to the next business
248	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
249	        // registration date (membership-number year segment, per-day create-limit) uses this
250	        // adjusted date.
251	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
252	        if (registrationDate == null) {
253	            registrationDate = LocalDate.now();
254	        }
255	        // Reject a supplied registration date that lies in the future (later than the
256	        // server's current date): an owner cannot be registered ahead of time.
257	        else if (registrationDate.isAfter(LocalDate.now())) {
258	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
259	        }
260	        registrationDate = toBusinessDay(registrationDate);
261	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
262	        // owners have already been registered on this (adjusted) business day.
263	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
264	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
265	        }
266	        HttpHeaders headers = new HttpHeaders();
267	        Owner owner = candidate;
268	        owner.setRegistrationDate(registrationDate);
269	        // Assign the customer code as '<REGION>-<HASH8>': the region derived from the owner's
270	        // postcode (falling back to the city, then 'UNKNOWN') and the first 8 upper-case hex
271	        // characters of the SHA-256 of the normalized telephone concatenated with the last name.
272	        owner.setCustomerCode(customerCode(owner));
273	        // Record how many existing owners already share this owner's first and last name
274	        // (compared case-insensitively) at the moment before this owner is created.
275	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
276	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
277	        // registered on this (adjusted) business day before this owner is created.
278	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
279	        // Record the size of this owner's household after this create: the number of existing
280	        // owners sharing the same household (i.e. the same computed householdId) plus this owner.
281	        owner.setHouseholdSize(countHouseholdMembers(owner) + 1);
282	        // Cap this owner's membership level at one above the current maximum membership level among
283	        // their existing household members. When the owner has no existing household member no cap
284	        // applies (a null cap; see OwnerMapper#membershipLevel).
285	        owner.setMembershipLevelCap(membershipLevelCap(owner));
286	        // Flag a possible (soft) duplicate: this owner is not a hard identity duplicate, but it
287	        // shares an existing owner's last name (case-insensitively) and postcode while carrying a
288	        // different telephone. When such a match exists, record it as 'possibleDuplicate' with
289	        // 'possibleDuplicateOf' set to the matching owner's id; otherwise it is not a possible
290	        // duplicate. A declared household member is an acknowledged member, not a suspected
291	        // duplicate, so it is never flagged.
292	        if (declaredMember) {
293	            owner.setPossibleDuplicate(false);
294	            owner.setPossibleDuplicateOf(null);
295	        }
296	        else {
297	            Owner softMatch = findPossibleDuplicate(owner);
298	            owner.setPossibleDuplicate(softMatch != null);
299	            owner.setPossibleDuplicateOf(softMatch == null ? null : softMatch.getId());
300	        }
301	        this.clinicService.saveOwner(owner);
302	        // Emit an audit line recording the new owner's id, customer code, registration date,
303	        // membership level and membership number.
304	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
305	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
306	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
307	        // Remember this create against its idempotency key so a later repeat returns the same
308	        // owner instead of creating a duplicate.
309	        if (idempotencyKey != null) {
310	            idempotentCreates.put(idempotencyKey, owner.getId());
311	        }
312	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
313	        headers.setLocation(UriComponentsBuilder.newInstance()
314	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
315	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
316	    }
317	
318	    /**
319	     * The non-blank {@code Idempotency-Key} header of the current request, or {@code null} when
320	     * absent, blank, or there is no bound request.
321	     */
322	    private static String currentIdempotencyKey() {
323	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
324	        if (!(attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttributes)) {
325	            return null;
326	        }
327	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
328	        return (key == null || key.isBlank()) ? null : key;
329	    }
330	
331	    /**
332	     * Validate and normalize the optional owner email in place.
333	     *
334	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
335	     * When present it must be a syntactically valid address; a valid address is
336	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
337	     * present but syntactically invalid, so the caller can reject with 400.
338	     */
339	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
340	        String email = ownerFieldsDto.getEmail();
341	        if (email == null || email.isBlank()) {
342	            ownerFieldsDto.setEmail(null);
343	            return true;
344	        }
345	        String normalized = email.trim().toLowerCase(Locale.ROOT);
346	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
347	            return false;
348	        }
349	        // Reject addresses whose domain is on the disposable-domain blocklist.
350	        String domain = normalized.substring(normalized.indexOf('@') + 1);
351	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
352	            return false;
353	        }
354	        ownerFieldsDto.setEmail(normalized);
355	        return true;
356	    }
357	
358	    /**
359	     * Validate the optional owner postcode in place.
360	     *
361	     * <p>An absent (or blank) postcode is allowed and is normalized to {@code null}.
362	     * When present it must be exactly 4 digits, and — when the owner's city maps to a
363	     * known region via {@link OwnerMapper#CITY_REGION} — it must fall within that
364	     * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
365	     * A city with no known region accepts any 4-digit postcode. Returns {@code false}
366	     * when a postcode is present but malformed or out of range, so the caller can
367	     * reject with 400.
368	     */
369	    private boolean normalizePostcode(OwnerFieldsDto ownerFieldsDto) {
370	        String postcode = ownerFieldsDto.getPostcode();
371	        if (postcode == null || postcode.isBlank()) {
372	            ownerFieldsDto.setPostcode(null);
373	            return true;
374	        }
375	        if (!postcode.matches("\\d{4}")) {
376	            return false;
377	        }
378	        String region = OwnerMapper.CITY_REGION.get(ownerFieldsDto.getCity());
379	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
380	        if (range != null) {
381	            int value = Integer.parseInt(postcode);
382	            if (value < range[0] || value > range[1]) {
383	                return false;
384	            }
385	        }
386	        return true;
387	    }
388	
389	    /**
390	     * Validate and normalize the owner's address fields in place, preferring the structured
391	     * form over the flat 'address' for backward compatibility.
392	     *
393	     * <p>When a non-blank {@code addressLine1} is supplied it is the structured form: both
394	     * {@code addressLine1} and (when present) {@code addressLine2} are normalized and stored
395	     * back, and {@code address} is set to the composed value — the normalized addressLine1,
396	     * with a single space and the normalized addressLine2 appended when addressLine2 is present.
397	     * Otherwise the flat {@code address} is normalized in place and the structured lines are
398	     * cleared. Returns {@code false} when no address is supplied in either form (both the
399	     * structured addressLine1 and the flat address are blank once normalized), so the caller
400	     * can reject with 400.
401	     */
402	    private boolean normalizeAddresses(OwnerFieldsDto ownerFieldsDto) {
403	        String rawLine1 = ownerFieldsDto.getAddressLine1();
404	        if (rawLine1 != null && !rawLine1.isBlank()) {
405	            String line1 = normalizeAddress(rawLine1);
406	            if (line1.isBlank()) {
407	                return false;
408	            }
409	            ownerFieldsDto.setAddressLine1(line1);
410	            String rawLine2 = ownerFieldsDto.getAddressLine2();
411	            String composed = line1;
412	            if (rawLine2 != null && !rawLine2.isBlank()) {
413	                String line2 = normalizeAddress(rawLine2);
414	                ownerFieldsDto.setAddressLine2(line2);
415	                composed = line1 + " " + line2;
416	            }
417	            else {
418	                ownerFieldsDto.setAddressLine2(null);
419	            }
420	            ownerFieldsDto.setAddress(composed);
421	            return true;
422	        }
423	        // No structured address: fall back to the flat 'address' input.
424	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
425	        if (canonicalAddress.isBlank()) {
426	            return false;
427	        }
428	        ownerFieldsDto.setAddress(canonicalAddress);
429	        ownerFieldsDto.setAddressLine1(null);
430	        ownerFieldsDto.setAddressLine2(null);
431	        return true;
432	    }
433	
434	    /**
435	     * Normalize an owner address: trim, collapse each run of whitespace to a single
436	     * space, upper-case, and expand common street-type abbreviations
437	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
438	     * A {@code null} value normalizes to the empty string.
439	     */
440	    private static String normalizeAddress(String value) {
441	        if (value == null) {
442	            return "";
443	        }
444	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
445	        if (collapsed.isEmpty()) {
446	            return "";
447	        }
448	        String[] tokens = collapsed.split(" ");
449	        StringBuilder sb = new StringBuilder(collapsed.length());
450	        for (int i = 0; i < tokens.length; i++) {
451	            if (i > 0) {
452	                sb.append(' ');
453	            }
454	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
455	        }
456	        return sb.toString();
457	    }
458	
459	    /**
460	     * The contact portion of an owner's derived identity key: its normalized telephone and
461	     * email ('&lt;normalizedTelephone&gt;|&lt;email or empty&gt;'), i.e. the identity key
462	     * without the household segment. Two owners share an identity when this value is equal;
463	     * because the telephone is part of it, members of one household with different telephones
464	     * do not collide. A {@code null} email contributes the empty string.
465	     */
466	    private static String identityContact(Owner owner) {
467	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
468	        String email = owner.getEmail() == null ? "" : owner.getEmail();
469	        return telephone + "|" + email;
470	    }
471	
472	    /**
473	     * Normalize a telephone number to E.164 form.
474	     *
475	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
476	     * explicit leading {@code '+'} and country code it is kept; otherwise the
477	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
478	     * dropped from the national digits. The result must contain 8 to 15 digits
479	     * after the {@code '+'}, and — for a recognised country calling code — exactly
480	     * the national-number length that code mandates ({@code '+61'} => 9 national
481	     * digits, {@code '+1'} => 10).
482	     *
483	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
484	     *         the input is absent or cannot form a valid E.164 number.
485	     */
486	    private static String toE164(String raw) {
487	        if (raw == null) {
488	            return null;
489	        }
490	        String trimmed = raw.trim();
491	        boolean hasCountryCode = trimmed.startsWith("+");
492	        // Strip spaces, dashes and brackets.
493	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
494	        String digits;
495	        if (hasCountryCode) {
496	            // Keep the explicit country code; drop the leading '+' for validation.
497	            digits = stripped.substring(1);
498	        } else {
499	            // No country code: assume '+61' and drop a single leading '0'.
500	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
501	            digits = "61" + national;
502	        }
503	        if (!digits.matches("\\d{8,15}")) {
504	            return null;
505	        }
506	        // For a recognised country calling code, enforce the exact national-number length it
507	        // mandates (e.g. '+61' => 9 national digits, '+1' => 10). Longer codes win so a '+61'
508	        // number is not mistaken for a '+6...' one. Unknown codes keep the generic 8-15 rule.
509	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet().stream()
510	                .sorted((a, b) -> b.length() - a.length()).toList()) {
511	            if (digits.startsWith(countryCode)) {
512	                int nationalLength = digits.length() - countryCode.length();
513	                if (nationalLength != NATIONAL_NUMBER_LENGTHS.get(countryCode)) {
514	                    return null;
515	                }
516	                break;
517	            }
518	        }
519	        return "+" + digits;
520	    }
521	
522	    /**
523	     * Count the existing owners whose first and last name match the given names,
524	     * compared case-insensitively. Used to record an owner's namesake count at the
525	     * moment before it is created.
526	     */
527	    private int countNamesakes(String firstName, String lastName) {
528	        return (int) this.clinicService.findAllOwners().stream()
529	            .filter(existing -> existing.getFirstName() != null
530	                && existing.getFirstName().equalsIgnoreCase(firstName)
531	                && existing.getLastName() != null
532	                && existing.getLastName().equalsIgnoreCase(lastName))
533	            .count();
534	    }
535	
536	    /**
537	     * Count the existing owners in the same household as the given owner, i.e. those sharing its
538	     * computed householdId (derived from the normalized last name and postcode). Used, together
539	     * with the owner being created, to derive the household size recorded on the owner.
540	     */
541	    private int countHouseholdMembers(Owner owner) {
542	        String householdId = ownerMapper.householdId(owner);
543	        return (int) this.clinicService.findAllOwners().stream()
544	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
545	            .count();
546	    }
547	
548	    /**
549	     * Compute the membership-level cap for the owner being created: one above the current maximum
550	     * effective membership level among its existing (non-deleted) household members, i.e. those
551	     * sharing its computed householdId. Each member's effective level is read through
552	     * {@link OwnerMapper#membershipLevel(Owner)}, so it already reflects any cap applied to that
553	     * member. Returns {@code null} when the owner has no existing household member, in which case
554	     * no cap applies.
555	     */
556	    private Integer membershipLevelCap(Owner owner) {
557	        String householdId = ownerMapper.householdId(owner);
558	        java.util.OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
559	            .filter(existing -> !existing.isDeleted())
560	            .filter(existing -> existing != owner)
561	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
562	            .mapToInt(existing -> ownerMapper.membershipLevel(existing))
563	            .max();
564	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
565	    }
566	
567	    /**
568	     * Find an existing owner that the given (not-yet-created) owner is a possible (soft) duplicate
569	     * of: one sharing the same last name (compared case-insensitively) and the same postcode, but
570	     * carrying a different normalized telephone. Owners without a postcode never match (the postcode
571	     * must be shared). When several existing owners match, the one with the lowest id is returned so
572	     * the result is deterministic. Returns {@code null} when there is no such match.
573	     */
574	    private Owner findPossibleDuplicate(Owner candidate) {
575	        if (candidate.getPostcode() == null) {
576	            return null;
577	        }
578	        return this.clinicService.findAllOwners().stream()
579	            .filter(existing -> !existing.isDeleted())
580	            .filter(existing -> existing.getLastName() != null
581	                && existing.getLastName().equalsIgnoreCase(candidate.getLastName())
582	                && candidate.getPostcode().equals(existing.getPostcode())
583	                && !candidate.getTelephone().equals(existing.getTelephone()))
584	            .min(java.util.Comparator.comparing(Owner::getId))
585	            .orElse(null);
586	    }
587	
588	    /**
589	     * Build the owner's customer code, formatted {@code '<REGION>-<HASH8>'}.
590	     *
591	     * <p>{@code REGION} is the region derived from the owner's postcode (see
592	     * {@link #deriveRegion}). {@code HASH8} is the first 8 upper-case hex characters of the
593	     * SHA-256 of the normalized telephone concatenated with the last name
594	     * (e.g. {@code 'NSW-1A2B3C4D'}).
595	     *
596	     * <p>When the computed code collides with an existing owner's customer code, it is
597	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more
598	     * that makes it unique.
599	     */
600	    private String customerCode(Owner owner) {
601	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
602	        String hash8 = sha256HexUpper(owner.getTelephone() + owner.getLastName(), 8);
603	        String base = region + "-" + hash8;
604	        Set<String> existing = this.clinicService.findAllOwners().stream()
605	            .map(Owner::getCustomerCode)
606	            .filter(java.util.Objects::nonNull)
607	            .collect(Collectors.toSet());
608	        if (!existing.contains(base)) {
609	            return base;
610	        }
611	        int n = 2;
612	        while (existing.contains(base + "-" + n)) {
613	            n++;
614	        }
615	        return base + "-" + n;
616	    }
617	
618	    /**
619	     * Derive the owner's region, preferring the postcode. The postcode is matched against
620	     * each region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); only when
621	     * it is absent or in no known range does this fall back to the fixed city-to-region table
622	     * (see {@link OwnerMapper#CITY_REGION}), and finally {@code 'UNKNOWN'}.
623	     */
624	    private static String deriveRegion(String postcode, String city) {
625	        if (postcode != null && postcode.matches("\\d{4}")) {
626	            int value = Integer.parseInt(postcode);
627	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
628	                int[] range = entry.getValue();
629	                if (value >= range[0] && value <= range[1]) {
630	                    return entry.getKey();
631	                }
632	            }
633	        }
634	        return OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
635	    }
636	
637	    /**
638	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
639	     * bytes of {@code value}.
640	     */
641	    private static String sha256HexUpper(String value, int length) {
642	        try {
643	            byte[] digest = MessageDigest.getInstance("SHA-256")
644	                .digest(value.getBytes(StandardCharsets.UTF_8));
645	            StringBuilder sb = new StringBuilder(digest.length * 2);
646	            for (byte b : digest) {
647	                sb.append(String.format("%02X", b));
648	            }
649	            return sb.substring(0, length);
650	        }
651	        catch (NoSuchAlgorithmException e) {
652	            throw new IllegalStateException(e);
653	        }
654	    }
655	
656	    /**
657	     * Count the existing owners located in the given city, compared case-insensitively.
658	     * Used to derive the per-city 4-digit sequence in the customer code.
659	     */
660	    private int countOwnersInCity(String city) {
661	        return (int) this.clinicService.findAllOwners().stream()
662	            .filter(existing -> existing.getCity() != null
663	                && existing.getCity().equalsIgnoreCase(city))
664	            .count();
665	    }
666	
667	    /**
668	     * Count the existing owners whose registration date is the given (adjusted business) date.
669	     * Used to enforce the per-day sign-up limit.
670	     */
671	    private int countOwnersRegisteredOn(LocalDate date) {
672	        return (int) this.clinicService.findAllOwners().stream()
673	            .filter(existing -> date.equals(existing.getRegistrationDate()))
674	            .count();
675	    }
676	
677	    /** Fixed public holidays the business-day roll skips. */
678	    private static final Set<LocalDate> HOLIDAYS = Set.of(
679	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
680	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
681	        LocalDate.parse("2026-12-28"));
682	
683	    /**
684	     * Roll a registration date forward onto a business day: a Saturday, Sunday, or listed
685	     * public holiday is moved forward to the next non-holiday weekday; a plain weekday is
686	     * returned unchanged.
687	     */
688	    private static LocalDate toBusinessDay(LocalDate date) {
689	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
690	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
691	            || HOLIDAYS.contains(date)) {
692	            date = date.plusDays(1);
693	        }
694	        return date;
695	    }
696	
697	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
698	    @Override
699	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
700	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
701	        if (currentOwner == null) {
702	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
703	        }
704	        if (!normalizeEmail(ownerFieldsDto)) {
705	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
706	        }
707	        if (!normalizePostcode(ownerFieldsDto)) {
708	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
709	        }
710	        if (!normalizeAddresses(ownerFieldsDto)) {
711	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
712	        }
713	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
714	        if (normalizedTelephone == null) {
715	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
716	        }
717	        currentOwner.setAddress(ownerFieldsDto.getAddress());
718	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
719	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
720	        currentOwner.setCity(ownerFieldsDto.getCity());
721	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
722	        currentOwner.setLastName(ownerFieldsDto.getLastName());
723	        currentOwner.setTelephone(normalizedTelephone);
724	        currentOwner.setEmail(ownerFieldsDto.getEmail());
725	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
726	        this.clinicService.saveOwner(currentOwner);
727	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
728	    }
729	
730	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
731	    @Transactional
732	    @Override
733	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
734	        Owner owner = this.clinicService.findOwnerById(ownerId);
735	        if (owner == null) {
736	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
737	        }
738	        // Soft-delete: flag the owner deleted and retain the record so it can still be
739	        // read back (with 'deleted' true) and is ignored by later duplicate/identity checks.
740	        owner.setDeleted(true);
741	        this.clinicService.saveOwner(owner);
742	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
743	    }
744	
745	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
746	    @Override
747	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
748	        Owner owner = this.clinicService.findOwnerById(ownerId);
749	        if (owner == null) {
750	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
751	        }
752	        HttpHeaders headers = new HttpHeaders();
753	        Pet pet = petMapper.toPet(petFieldsDto);
754	        owner.setId(ownerId);
755	        pet.setOwner(owner);
756	        pet.getType().setName(null);
757	        this.clinicService.savePet(pet);
758	        PetDto petDto = petMapper.toPetDto(pet);
759	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
760	            .buildAndExpand(pet.getId()).toUri());
761	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
762	    }
763	
764	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
765	    @Override
766	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
767	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
768	        if (currentOwner != null) {
769	            Pet currentPet = this.clinicService.findPetById(petId);
770	            if (currentPet != null) {
771	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
772	                currentPet.setName(petFieldsDto.getName());
773	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
774	                this.clinicService.savePet(currentPet);
775	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
776	            }
777	        }
778	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
779	    }
780	
781	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
782	    @Override
783	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
784	        HttpHeaders headers = new HttpHeaders();
785	        Visit visit = visitMapper.toVisit(visitFieldsDto);
786	        Pet pet = new Pet();
787	        pet.setId(petId);
788	        visit.setPet(pet);
789	        this.clinicService.saveVisit(visit);
790	        VisitDto visitDto = visitMapper.toVisitDto(visit);
791	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
792	            .buildAndExpand(visit.getId()).toUri());
793	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
794	    }
795	
796	
797	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
798	    @Override
799	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
800	        Owner owner = this.clinicService.findOwnerById(ownerId);
801	        if (owner != null) {
802	            Pet pet = owner.getPet(petId);
803	            if (pet != null) {
804	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
805	            }
806	        }
807	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
808	    }
809	}
