60	    /**
61	     * The owner's salutation: the supplied title, a single space and the last name when a
62	     * title was supplied (e.g. 'DR Who'), or just the last name when no title (null or blank)
63	     * was given.
64	     */
65	    default String salutation(Owner owner) {
66	        String title = owner.getTitle();
67	        if (title == null || title.isBlank()) {
68	            return owner.getLastName();
69	        }
70	        return title + " " + owner.getLastName();
71	    }
72	
73	    /**
74	     * The owner's age band, derived from the supplied birthDate as at the
75	     * registrationDate: 'MINOR' when under 18, 'ADULT' when 18-64, and 'SENIOR' when
76	     * 65 or older. Returns {@code null} when no birthDate (or registrationDate) is
77	     * available, so the field is omitted for owners without a supplied birth date.
78	     */
79	    default String ageBand(Owner owner) {
80	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
81	            return null;
82	        }
83	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
84	        if (age < 18) {
85	            return "MINOR";
86	        }
87	        if (age < 65) {
88	            return "ADULT";
89	        }
90	        return "SENIOR";
91	    }
92	
93	    /**
94	     * The owner's preferred contact channel: 'EMAIL' when an email address is present,
95	     * otherwise 'PHONE'.
96	     */
97	    default String contactPreference(Owner owner) {
98	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
99	        return hasEmail ? "EMAIL" : "PHONE";
100	    }
101	
102	    /**
103	     * The owner's region, read from the {@code <REGION>-<HASH8>} customer code assigned on
104	     * creation: the segment before the first '-'. Returns 'UNKNOWN' when no customer code has
105	     * been assigned (e.g. legacy owners predating the region-and-hash identity).
106	     */
107	    default String locality(Owner owner) {
108	        String code = owner.getCustomerCode();
109	        if (code != null) {
110	            int dash = code.indexOf('-');
111	            if (dash > 0) {
112	                return code.substring(0, dash);
113	            }
114	        }
115	        return "UNKNOWN";
116	    }
117	
118	    /**
119	     * The owner's IANA timezone, derived from its locality/region via the fixed
120	     * region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
121	     * QLD -> Australia/Brisbane). Returns {@code null} when the region is not one of
122	     * these, so the field is omitted for owners whose region is unknown.
123	     */
124	    default String timezone(Owner owner) {
125	        return REGION_TIMEZONE.get(locality(owner));
126	    }
127	
128	    /**
129	     * The owner's membership points. Starts at 0; gains 2 when an email address is present,
130	     * 1 when the owner has no namesakes (namesakeCount is 0), 2 for a household of 3 or more
131	     * (householdSize is 3 or greater), and 3 when the owner's tenure spans at least one
132	     * elapsed fiscal year (the current fiscal year, starting 1 July, is later than the
133	     * registrationDate's fiscal year). Because a newly created owner registers in the current
134	     * fiscal year, the tenure points are only earned once the fiscal year has rolled over
135	     * since registration.
136	     */
137	    default Integer membershipPoints(Owner owner) {
138	        int points = 0;
139	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
140	        if (hasEmail) {
141	            points += 2;
142	        }
143	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
144	        if (noNamesakes) {
145	            points += 1;
146	        }
147	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
148	            points += 2;
149	        }
150	        if (owner.getRegistrationDate() != null
151	            && fiscalEndYear(java.time.LocalDate.now())
152	                - fiscalEndYear(owner.getRegistrationDate()) >= 1) {
153	            points += 3;
154	        }
155	        return points;
156	    }
157	
158	    /**
159	     * The owner's numeric membership level, derived from {@link #membershipPoints(Owner)}:
160	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4
161	     * for 6 or more points.
162	     *
163	     * <p>The derived level is then capped by the owner's {@code membershipLevelCap} when one is
164	     * present: a new owner's level cannot exceed one above the current maximum membership level
165	     * among their existing household members, so the cap (recorded on the owner at creation as
166	     * that maximum plus one) is applied here. A {@code null} cap means the owner had no existing
167	     * household member, so no cap applies.
168	     */
169	    default Integer membershipLevel(Owner owner) {
170	        int points = membershipPoints(owner);
171	        int level;
172	        if (points <= 1) {
173	            level = 1;
174	        }
175	        else if (points <= 3) {
176	            level = 2;
177	        }
178	        else if (points <= 5) {
179	            level = 3;
180	        }
181	        else {
182	            level = 4;
183	        }
184	        Integer cap = owner.getMembershipLevelCap();
185	        if (cap != null && level > cap) {
186	            return cap;
187	        }
188	        return level;
189	    }
190	
191	    /**
192	     * A single Luhn check digit (0-9) computed over the digits contained in the owner's
193	     * customerCode. Returns {@code null} when the customerCode has not been assigned.
194	     */
195	    default Integer checkDigit(Owner owner) {
196	        if (owner.getCustomerCode() == null) {
197	            return null;
198	        }
199	        String s = owner.getCustomerCode();
200	        int sum = 0;
201	        boolean dbl = true;
202	        for (int i = s.length() - 1; i >= 0; i--) {
203	            char c = s.charAt(i);
204	            if (c < '0' || c > '9') {
205	                continue;
206	            }
207	            int d = c - '0';
208	            if (dbl) {
209	                d *= 2;
210	                if (d > 9) {
211	                    d -= 9;
212	                }
213	            }
214	            sum += d;
215	            dbl = !dbl;
216	        }
217	        return (10 - (sum % 10)) % 10;
218	    }
219	
220	    /**
221	     * The fiscal year, starting on 1 July, that a date falls in, expressed as the last two
222	     * digits of the calendar year in which the fiscal year ends. Dates on or after 1 July
223	     * belong to the fiscal year ending the following calendar year (e.g. 2026-08-10 -&gt; 27);
224	     * dates before 1 July belong to the fiscal year ending in the same calendar year
225	     * (e.g. 2026-03-01 -&gt; 26).
226	     */
227	    private static int fiscalEndYear(java.time.LocalDate date) {
228	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
229	    }
230	
231	    private static int fiscalYearOf(java.time.LocalDate date) {
232	        return fiscalEndYear(date) % 100;
233	    }
234	
235	    /**
236	     * The owner's fiscal year, formatted 'FY&lt;YY&gt;' where YY is the two-digit fiscal year
237	     * (starting 1 July) of the business-day-adjusted registrationDate (e.g. 'FY27'). Returns
238	     * {@code null} when no registrationDate is available.
239	     */
240	    default String fiscalYear(Owner owner) {
