242	            return null;
243	        }
244	        return String.format("FY%02d", fiscalYearOf(owner.getRegistrationDate()));
245	    }
246	
247	    /**
248	     * The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY
249	     * is the two-digit fiscal year (starting 1 July) of the registrationDate
250	     * (e.g. 'NSW-1A2B3C4D-M27').
251	     */
252	    default String membershipNumber(Owner owner) {
253	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
254	            return null;
255	        }
256	        return String.format("%s-M%02d", owner.getCustomerCode(),
257	            fiscalYearOf(owner.getRegistrationDate()));
258	    }
259	
260	    /**
261	     * Known E.164 country calling codes used to split the stored telephone into its
262	     * country code and national number for display. Longer codes are matched first so a
263	     * '+61' number is not mistaken for a '+6...' one.
264	     */
265	    java.util.List<String> COUNTRY_CODES = java.util.List.of("61", "1");
266	
267	    /**
268	     * The stored E.164 telephone formatted for humans: the country code, a space, and the
269	     * national digits grouped in threes (e.g. '+61412345678' becomes '+61 412 345 678').
270	     * Returns the stored value unchanged when it is {@code null} or not in the expected
271	     * '+'-prefixed all-digits E.164 form.
272	     */
273	    default String telephoneDisplay(Owner owner) {
274	        String telephone = owner.getTelephone();
275	        if (telephone == null || !telephone.startsWith("+")) {
276	            return telephone;
277	        }
278	        String digits = telephone.substring(1);
279	        if (digits.isEmpty() || !digits.chars().allMatch(Character::isDigit)) {
280	            return telephone;
281	        }
282	        String countryCode = COUNTRY_CODES.stream()
283	            .filter(digits::startsWith)
284	            .findFirst()
285	            .orElse(digits.substring(0, 1));
286	        String national = digits.substring(countryCode.length());
287	        StringBuilder sb = new StringBuilder("+").append(countryCode);
288	        for (int i = 0; i < national.length(); i++) {
289	            if (i % 3 == 0) {
290	                sb.append(' ');
291	            }
292	            sb.append(national.charAt(i));
293	        }
294	        return sb.toString();
295	    }
296	
297	    /**
298	     * The upper-cased first letters of firstName and lastName, dot-separated with a
299	     * trailing dot, e.g. 'J.S.'.
300	     */
301	    default String initials(Owner owner) {
302	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
303	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
304	    }
305	
306	    /**
307	     * A stable identifier for the owner's household, derived deterministically from the
308	     * normalized last name and the postcode. Every owner sharing the same last name
309	     * (trimmed, lower-cased, whitespace collapsed) and postcode therefore receives the
310	     * same identifier: the first twelve upper-case hex characters of the SHA-256 of
311	     * '&lt;normalizedLastName&gt;|&lt;postcode&gt;'. A {@code null} postcode contributes
312	     * the empty string.
313	     */
314	    default String householdId(Owner owner) {
315	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
316	        String key = normalizeHouseholdKey(owner.getLastName()) + "|" + postcode;
317	        try {
318	            byte[] digest = MessageDigest.getInstance("SHA-256")
319	                .digest(key.getBytes(StandardCharsets.UTF_8));
320	            StringBuilder sb = new StringBuilder();
321	            for (int i = 0; i < 6; i++) {
322	                sb.append(String.format("%02X", digest[i]));
323	            }
324	            return sb.toString();
325	        }
326	        catch (java.security.NoSuchAlgorithmException e) {
327	            throw new IllegalStateException(e);
328	        }
329	    }
330	
331	    /**
332	     * The owner's derived identity key: the single value onto which all duplicate
333	     * detection is consolidated, formatted
334	     * '&lt;normalizedTelephone&gt;|&lt;email or empty&gt;|&lt;householdId&gt;'.
335	     * The telephone and email are the owner's stored (already normalized) values;
336	     * a {@code null} email contributes the empty string. Two owners are duplicates
337	     * only when their whole identity keys are equal.
338	     */
339	    default String identityKey(Owner owner) {
340	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
341	        String email = owner.getEmail() == null ? "" : owner.getEmail();
342	        return telephone + "|" + email + "|" + householdId(owner);
343	    }
344	
345	    private static String normalizeHouseholdKey(String value) {
346	        if (value == null) {
347	            return "";
348	        }
349	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
350	    }
351	
