/**
 * The owner's derived identity key: the single value onto which all duplicate
 * detection is consolidated. It is the full lower-case hex SHA-256 digest of
 * '&lt;normalizedTelephone&gt;|&lt;lowerEmail&gt;|&lt;soundex(lastName)&gt;'.
 * The telephone and email are the owner's stored (already normalized) values;
 * a {@code null} email contributes the empty string, and the last name is reduced
 * to its Soundex code so surnames that sound alike share the same segment. Two
 * owners are duplicates only when their whole identity keys are equal.
 */
default String identityKey(Owner owner) {
    String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
    String email = owner.getEmail() == null ? "" : owner.getEmail();
    String key = telephone + "|" + email + "|" + soundex(owner.getLastName());
    try {
        byte[] digest = MessageDigest.getInstance("SHA-256")
            .digest(key.getBytes(StandardCharsets.UTF_8));
        StringBuilder sb = new StringBuilder(digest.length * 2);
        for (byte b : digest) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
    catch (java.security.NoSuchAlgorithmException e) {
        throw new IllegalStateException(e);
    }
}

/**
 * The American Soundex code of a name: its first letter followed by three digits
 * encoding the remaining consonants (b,f,p,v=1; c,g,j,k,q,s,x,z=2; d,t=3; l=4;
 * m,n=5; r=6), with adjacent equal codes (and codes separated only by h/w)
 * collapsed and vowels acting as separators. The result is upper-cased and padded
 * with trailing zeros to exactly four characters. A {@code null}/blank or letter-less
 * name yields the empty string.
 */
static String soundex(String value) {
    if (value == null) {
        return "";
    }
    String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
    if (letters.isEmpty()) {
        return "";
    }
    StringBuilder code = new StringBuilder();
    code.append(letters.charAt(0));
    char previous = soundexCode(letters.charAt(0));
    for (int i = 1; i < letters.length() && code.length() < 4; i++) {
        char c = letters.charAt(i);
        if (c == 'H' || c == 'W') {
            // Transparent: does not emit a digit nor reset the previous code.
            continue;
        }
        char digit = soundexCode(c);
        if (digit != '0' && digit != previous) {
            code.append(digit);
        }
        // Vowels ('0') reset the run so a later equal consonant is coded again.
        previous = digit;
    }
    while (code.length() < 4) {
        code.append('0');
    }
    return code.toString();
}

private static char soundexCode(char c) {
    return switch (c) {
        case 'B', 'F', 'P', 'V' -> '1';
        case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
        case 'D', 'T' -> '3';
        case 'L' -> '4';
        case 'M', 'N' -> '5';
        case 'R' -> '6';
        default -> '0';
    };
}

private static String normalizeHouseholdKey(String value) {
    if (value == null) {
        return "";
    }
    return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
}

